    aShuffleTable[1] = 1;
    aShuffleTable[2] = 2;
    aShuffleTable[3] = 3;
    aShuffleTable[4] = 4;
    aShuffleTable[5] = 5;
    aShuffleTable[6] = 6;
    aShuffleTable[7] = 7;
    aShuffleTable[9] = 9;
    aShuffleTable[10] = 10;
    aShuffleTable[0xb] = 0xb;
    aShuffleTable[0xc] = 0xc;
    aShuffleTable[0xd] = 0xd;
    aShuffleTable[0xe] = 0xe;
